import { Card, Group, Text, ThemeIcon, Box } from "@mantine/core";
import { IconArrowUp, IconArrowDown, IconUsers, IconCreditCard, IconShoppingCart, IconChartLine } from "@tabler/icons-react";

const iconMap = {
  users: IconUsers,
  "credit-card": IconCreditCard,
  "shopping-cart": IconShoppingCart,
  "chart-line": IconChartLine,
};

function StatsCard({ stat }) {
  const safeStat = stat ?? {};
  const Icon = iconMap[safeStat.icon] ?? IconUsers;
  const TrendIcon = safeStat.trend === "up" ? IconArrowUp : IconArrowDown;
  const trendColor = safeStat.trend === "up" ? "secondary" : "red";

  return (
    <Card>
      <Group justify="space-between" align="flex-start">
        <Box>
          <Text size="xs" c="dimmed" tt="uppercase" fw={600} mb={4}>
            {safeStat.title ?? "Metric"}
          </Text>
          <Text size="2rem" fw={700} lh={1.2}>
            {safeStat.value ?? "0"}
          </Text>
          <Group gap={4} mt={8}>
            <ThemeIcon color={trendColor} size="sm" variant="light">
              <TrendIcon size={12} />
            </ThemeIcon>
            <Text size="xs" c={trendColor} fw={500}>
              {safeStat.change ?? "0%"}
            </Text>
            <Text size="xs" c="dimmed">
              from last month
            </Text>
          </Group>
        </Box>
        <ThemeIcon size="xl" variant="light" color="primary">
          <Icon size={24} />
        </ThemeIcon>
      </Group>
    </Card>
  );
}

export default StatsCard;

import { Paper, Text, Group, Box, Skeleton, Center } from "@mantine/core";
import { useMediaQuery } from "@mantine/hooks";

function MockChart({ chart, loading = false }) {
  const safeChart = chart ?? {};
  const safeData = Array.isArray(safeChart.data) ? safeChart.data : [];
  const isMobile = useMediaQuery("(max-width: 768px)");

  if (loading) {
    return (
      <Paper>
        <Skeleton height={24} width="60%" mb="sm" />
        <Skeleton height={isMobile ? 180 : 240} />
      </Paper>
    );
  }

  const chartHeight = isMobile ? 180 : 240;

  return (
    <Paper>
      <Text size="sm" fw={600} mb="md">
        {safeChart.title ?? "Chart"}
      </Text>
      <Box h={chartHeight} style={{ position: "relative", backgroundColor: "var(--mantine-color-gray-0)" }}>
        <Center h="100%">
          <Text c="dimmed" size="sm">
            {safeChart.type === "line" && "📈 Line chart visualization"}
            {safeChart.type === "bar" && "📊 Bar chart visualization"}
            {safeChart.type === "pie" && "🥧 Pie chart visualization"}
          </Text>
        </Center>
      </Box>
      {safeChart.type === "bar" && safeData.length > 0 && (
        <Group justify="center" mt="sm" gap="xs">
          {safeData.map((item, index) => (
            <Box key={index} style={{ textAlign: "center" }}>
              <Text size="xs" c="dimmed">{item.day ?? item.date ?? "?"}</Text>
            </Box>
          ))}
        </Group>
      )}
    </Paper>
  );
}

export default MockChart;

import { Title, Text, Box } from "@mantine/core";

function SectionHeading({ title, description }) {
  return (
    <Box mb="lg">
      <Title order={2} size="h3" fw={600} mb={description ? 4 : 0}>
        {title ?? "Section"}
      </Title>
      {description && (
        <Text c="dimmed" size="sm">
          {description}
        </Text>
      )}
    </Box>
  );
}

export default SectionHeading;

import { AppShell, NavLink, Group, Box, Text, ActionIcon, ScrollArea } from "@mantine/core";
import { IconDashboard, IconUsers, IconPackage, IconShoppingCart, IconChartBar, IconSettings, IconChevronLeft, IconChevronRight, IconMenu2 } from "@tabler/icons-react";
import { useDisclosure, useMediaQuery } from "@mantine/hooks";
import navigationItems from "../../data/navigationItems";

const iconMap = {
  dashboard: IconDashboard,
  users: IconUsers,
  package: IconPackage,
  "shopping-cart": IconShoppingCart,
  "chart-bar": IconChartBar,
  settings: IconSettings,
};

function SidebarNav() {
  const [collapsed, { toggle }] = useDisclosure(false);
  const isMobile = useMediaQuery("(max-width: 768px)");
  const safeNavItems = Array.isArray(navigationItems) ? navigationItems : [];

  const navLinks = safeNavItems.map((item) => {
    const Icon = iconMap[item.icon] ?? IconDashboard;
    return (
      <NavLink
        key={item.id}
        href={item.route ?? "#"}
        label={collapsed ? undefined : item.label ?? "Item"}
        leftSection={<Icon size={18} stroke={1.5} />}
        active={item.id === "dashboard"}
        variant="filled"
        color="primary"
      />
    );
  });

  if (isMobile) {
    return null;
  }

  return (
    <AppShell.Navbar p="xs" style={{ transition: "width 200ms ease" }}>
      <Group justify="flex-end" mb="xs">
        <ActionIcon
          variant="subtle"
          color="gray"
          onClick={toggle}
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
        >
          {collapsed ? <IconChevronRight size={16} /> : <IconChevronLeft size={16} />}
        </ActionIcon>
      </Group>
      <ScrollArea>
        {navLinks}
      </ScrollArea>
    </AppShell.Navbar>
  );
}

export default SidebarNav;

import { SimpleGrid, Skeleton, Group } from "@mantine/core";
import { useMediaQuery } from "@mantine/hooks";
import StatsCard from "../common/StatsCard";
import SectionHeading from "../common/SectionHeading";
import mockStats from "../../data/mockStats";

function StatsOverview({ loading = false }) {
  const isMobile = useMediaQuery("(max-width: 768px)");
  const safeStats = Array.isArray(mockStats) ? mockStats : [];

  if (loading) {
    return (
      <div>
        <SectionHeading title="Overview Statistics" description="Key performance metrics at a glance" />
        <SimpleGrid cols={isMobile ? 1 : 2} spacing="md">
          {[1, 2, 3, 4].map((item) => (
            <Skeleton key={item} height={120} />
          ))}
        </SimpleGrid>
      </div>
    );
  }

  return (
    <div>
      <SectionHeading title="Overview Statistics" description="Key performance metrics at a glance" />
      <SimpleGrid cols={isMobile ? 1 : 2} spacing="md">
        {safeStats.map((stat) => (
          <StatsCard key={stat?.id ?? Math.random()} stat={stat} />
        ))}
      </SimpleGrid>
    </div>
  );
}

export default StatsOverview;

