import { Table, Pagination, Group, Text, Badge, Avatar, Box, Skeleton, Center } from "@mantine/core";
import { useDisclosure, useMediaQuery } from "@mantine/hooks";
import { useState } from "react";
import SectionHeading from "../common/SectionHeading";
import mockActivity from "../../data/mockActivity";

function ActivityTable({ loading = false }) {
  const isMobile = useMediaQuery("(max-width: 768px)");
  const [activePage, setPage] = useState(1);
  const itemsPerPage = 5;

  const safeActivity = Array.isArray(mockActivity) ? mockActivity : [];
  const totalPages = Math.max(1, Math.ceil(safeActivity.length / itemsPerPage));

  const paginatedData = safeActivity.slice(
    (activePage - 1) * itemsPerPage,
    activePage * itemsPerPage
  );

  const getStatusColor = (status) => {
    switch (status) {
      case "success":
        return "secondary";
      case "warning":
        return "yellow";
      case "error":
        return "red";
      default:
        return "gray";
    }
  };

  const formatTimestamp = (timestamp) => {
    if (!timestamp) return "—";
    try {
      const date = new Date(timestamp);
      return date.toLocaleString(undefined, {
        month: "short",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return "—";
    }
  };

  if (loading) {
    return (
      <div>
        <SectionHeading title="Recent Activity" description="Latest user actions and system events" />
        <Box>
          {[1, 2, 3, 4, 5].map((row) => (
            <Skeleton key={row} height={50} mb="xs" />
          ))}
        </Box>
      </div>
    );
  }

  const rows = paginatedData.map((item) => (
    <Table.Tr key={item?.id ?? Math.random()}>
      <Table.Td>
        <Group gap="sm">
          <Avatar size="sm" name={item?.user ?? "Unknown"} color="primary">
            {item?.avatar ?? "?"}
          </Avatar>
          <Text size="sm" fw={500}>
            {item?.user ?? "Unknown User"}
          </Text>
        </Group>
      </Table.Td>
      <Table.Td>
        <Text size="sm" lineClamp={isMobile ? 1 : 2}>
          {item?.action ?? "—"}
        </Text>
      </Table.Td>
      <Table.Td>
        <Text size="sm" c="dimmed">
          {formatTimestamp(item?.timestamp)}
        </Text>
      </Table.Td>
      <Table.Td>
        <Badge color={getStatusColor(item?.status)} variant="light">
          {item?.status ?? "unknown"}
        </Badge>
      </Table.Td>
    </Table.Tr>
  ));

  return (
    <div>
      <SectionHeading title="Recent Activity" description="Latest user actions and system events" />
      <Box style={{ overflowX: isMobile ? "auto" : "visible" }}>
        <Table>
          <Table.Thead>
            <Table.Tr>
              <Table.Th>User</Table.Th>
              <Table.Th>Action</Table.Th>
              <Table.Th>Timestamp</Table.Th>
              <Table.Th>Status</Table.Th>
            </Table.Tr>
          </Table.Thead>
          <Table.Tbody>
            {rows.length > 0 ? rows : (
              <Table.Tr>
                <Table.Td colSpan={4}>
                  <Center py="xl">
                    <Text c="dimmed">No recent activity to display</Text>
                  </Center>
                </Table.Td>
              </Table.Tr>
            )}
          </Table.Tbody>
        </Table>
      </Box>
      {safeActivity.length > itemsPerPage && (
        <Group justify="center" mt="md">
          <Pagination
            total={totalPages}
            value={activePage}
            onChange={setPage}
            size={isMobile ? "sm" : "md"}
          />
        </Group>
      )}
    </div>
  );
}

export default ActivityTable;

import { AppShell, Burger, Group, Text, Drawer, ScrollArea, NavLink } from "@mantine/core";
import { useDisclosure, useMediaQuery } from "@mantine/hooks";
import { IconDashboard, IconUsers, IconPackage, IconShoppingCart, IconChartBar, IconSettings } from "@tabler/icons-react";
import DashboardHeader from "./components/layout/DashboardHeader";
import SidebarNav from "./components/layout/SidebarNav";
import StatsOverview from "./components/sections/StatsOverview";
import ChartsSection from "./components/sections/ChartsSection";
import ActivityTable from "./components/sections/ActivityTable";
import navigationItems from "./data/navigationItems";

const iconMap = {
  dashboard: IconDashboard,
  users: IconUsers,
  package: IconPackage,
  "shopping-cart": IconShoppingCart,
  "chart-bar": IconChartBar,
  settings: IconSettings,
};

function App() {
  const [mobileNavOpened, { toggle: toggleMobileNav, close: closeMobileNav }] = useDisclosure(false);
  const isMobile = useMediaQuery("(max-width: 768px)");
  const safeNavItems = Array.isArray(navigationItems) ? navigationItems : [];

  const mobileNavLinks = safeNavItems.map((item) => {
    const Icon = iconMap[item.icon] ?? IconDashboard;
    return (
      <NavLink
        key={item.id}
        href={item.route ?? "#"}
        label={item.label ?? "Item"}
        leftSection={<Icon size={18} stroke={1.5} />}
        active={item.id === "dashboard"}
        variant="filled"
        color="primary"
        onClick={closeMobileNav}
      />
    );
  });

  return (
    <AppShell
      header={{ height: 60 }}
      navbar={{ width: { base: 260 }, breakpoint: "sm", collapsed: { mobile: true } }}
      padding="md"
    >
      <AppShell.Header>
        <Group justify="space-between" h="100%" px="md" py="xs">
          <Group>
            {isMobile && (
              <Burger
                opened={mobileNavOpened}
                onClick={toggleMobileNav}
                aria-label="Toggle navigation"
                size="sm"
              />
            )}
            <Text size="xl" fw={700}>
              Admin Dashboard
            </Text>
          </Group>
        </Group>
      </AppShell.Header>

      <AppShell.Navbar p="xs" hiddenFrom="sm">
        <ScrollArea>
          {mobileNavLinks}
        </ScrollArea>
      </AppShell.Navbar>

      <AppShell.Main>
        <div style={{ maxWidth: "1400px", margin: "0 auto" }}>
          <StatsOverview />
          <ChartsSection />
          <ActivityTable />
        </div>
      </AppShell.Main>
    </AppShell>
  );
}

export default App;
